let studioData={producer:null,artists:[],tracks:[]};
const bioField=(label,name,value='',hint='')=>`<label class="form-field">${label}<textarea name="${name}" maxlength="1000" placeholder="${esc(hint)}">${esc(value)}</textarea><small class="field-help">최대 1,000자</small></label>`;
const genreField=(value='K-POP')=>`<label class="form-field">장르<select name="genre">${genres.slice(1).map(g=>`<option ${g===value?'selected':''}>${g}</option>`).join('')}</select></label>`;
const profileImageURL=(p,kind)=>p?.image_version?`/media/${kind}/${p.id}?v=${p.image_version}`:'';
function imageField(label,name,src='',round=false){return `<div class="image-field ${round?'is-portrait':''}"><div class="image-preview">${src?`<img src="${esc(src)}" alt="${label} 미리보기">`:`<span>${icon('plus')}</span>`}</div><div class="image-field-controls"><label class="form-field">${label}<input type="file" name="${name}" accept="image/jpeg,image/png,image/webp" data-image-input></label><p class="field-help">JPG · PNG · WebP / 최대 5MB<br>정사각형 이미지를 권장해요.</p><span class="image-selection" role="status"></span><button type="button" class="text-link" data-reset-image hidden>선택 취소</button></div></div>`;}
function uploadHTML(d){const p=d.producer;return heading('음원 업로드','음악과 창작자의 이야기를 함께 들려주세요.')+`<div class="upload-layout"><form id="upload-form" class="surface upload-form"><div class="form-section-heading"><span>01</span><h2>음악과 앨범 커버</h2></div><label class="file-zone">${icon('upload')}<strong>원본 음원 선택</strong><span>WAV · FLAC · MP3 / 최대 80MB</span><input name="audio" type="file" accept=".wav,.flac,.mp3" required aria-label="원본 음원 선택"></label>${imageField('앨범 / 싱글 커버','cover')}<div class="form-section-heading"><span>02</span><h2>곡 정보</h2></div>${formField('곡 제목','title','text','','required maxlength="120"')}${genreField()}${formField('태그 (쉼표로 구분)','tags','text','','maxlength="300" placeholder="예: 새벽, 드라이브, 감성"')}<label class="form-field">곡 소개<textarea name="description" maxlength="4000" placeholder="음악에 담은 이야기, 가사와 분위기를 소개해주세요."></textarea></label><div class="form-section-heading"><span>03</span><h2>AI 가수 · 아티스트</h2></div>${d.artists.length?`<label class="form-field">아티스트 선택<select name="artist_id" id="upload-artist"><option value="">새 AI 아티스트 만들기</option>${d.artists.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></label>`:''}<div id="upload-artist-fields">${artistUploadFields()}</div><div class="form-section-heading"><span>04</span><h2>작곡가 · 제작자</h2></div><p class="field-help">음악을 만드는 사람의 공개 프로필입니다. 변경하면 기존 곡에도 함께 반영됩니다.</p>${imageField('작곡가 / 제작자 사진','producer_image',profileImageURL(p,'producer'),true)}${formField('작곡가 / 제작자 이름','producer','text',p?.name||me.name,'required maxlength="60"')}${bioField('작곡가 / 제작자 소개','producer_bio',p?.bio||'','작업 스타일, 음악 활동, 전하고 싶은 이야기를 소개해주세요.')}${lyricsEditorHTML()}<div class="form-section-heading"><span>06</span><h2>제작 크레딧</h2></div>${formField('사용한 AI 도구','ai_tool','text','','required maxlength="100" placeholder="예: Suno, Udio"')}${participationFields()}<label class="checkbox-line rights-check"><input name="is_ai" type="checkbox" required> AI를 활용해 제작한 음악입니다.</label><label class="checkbox-line rights-check"><input name="rights" type="checkbox" required> 이 음원과 이미지들을 업로드하고 공개할 권리를 보유하고 있습니다. 무단 복제, 타인의 음성 복제, 권리 없는 재업로드가 아닙니다.</label>${karaokeCheckHTML()}<button class="primary-button" id="upload-submit">음원 업로드 ${icon('upload')}</button><div class="upload-progress" hidden><progress max="100" value="0"></progress><p role="status"></p></div><p class="form-error" role="alert"></p></form><aside class="surface upload-guide"><span class="eyebrow">MADE BY YOU</span><h2>음악의 첫인상부터<br>당신의 이야기까지.</h2><p>앨범 커버는 곡 목록과 플레이어에, AI 가수와 작곡가 사진·소개는 각 프로필에 표시됩니다.</p><p>이미지는 선택 사항입니다. 스튜디오에서 사진과 소개를 언제든 수정할 수 있어요.</p><hr><p>음원은 5초부터 20분까지. 업로드 후 감상용 음원과 60초 미리 듣기를 자동으로 만들고 공개합니다.</p></aside></div>`;}
function artistUploadFields(a){return `${a?'<p class="field-help">선택한 아티스트의 공통 프로필을 수정합니다. 기존 곡에도 반영됩니다.</p>':''}${imageField('AI 가수 / 아티스트 사진','artist_image',profileImageURL(a,'artist'),true)}${formField('AI 가수 / 아티스트 이름','artist','text',a?.name||'','required maxlength="60"')}${bioField('AI 가수 / 아티스트 소개','artist_bio',a?.bio||'','목소리, 성격, 음악 스타일과 세계관을 소개해주세요.')}`;}
function participationFields(value=''){return `<div class="participation">사람이 참여한 부분 ${['작사','작곡','편곡','보컬','믹싱'].map(v=>`<label><input type="checkbox" name="participation" value="${v}" ${value.split(',').map(s=>s.trim()).includes(v)?'checked':''}>${v}</label>`).join('')}</div>`;}
function studioHTML(d){return heading('창작자 스튜디오','음악, 이미지, 프로필을 한곳에서 관리하세요.')+`<div class="stats-grid"><div class="stat-card"><span>공개한 음악</span><strong>${d.tracks.filter(t=>t.status==='published').length}</strong></div><div class="stat-card"><span>업로드 · 변환 중</span><strong>${d.tracks.filter(t=>['queued','processing','uploading'].includes(t.status)).length}</strong></div><div class="stat-card"><span>AI 아티스트</span><strong>${d.artists.length}</strong></div></div><div class="section-heading"><h2>내 음원 · 앨범 커버</h2><a class="primary-button" href="#upload">음원 업로드 ${icon('plus')}</a></div><div class="surface">${d.tracks.length?d.tracks.map(t=>`<div class="studio-track"><div class="studio-track-title">${cover(t,'mini-cover')}<div><strong>${esc(t.title)}</strong><p>${{uploading:'파일 전송 대기',queued:'변환 대기',processing:'음원 변환 중',published:'공개됨',hidden:'비공개',failed:'변환 실패'}[t.status]}</p>${alignmentBadge(t.alignment_state)}${t.error?`<small class="form-error">${esc(t.error)}</small>`:''}</div></div><div class="inline-actions"><a class="small-button" href="#manage/${t.id}">${t.alignment_state==='ready'?'자동 가사 확인 · 저장':'커버 · 가사 · 정보 수정'}</a>${t.status==='published'?`<a class="small-button" href="#song/${t.id}">곡 보기</a><button class="small-button" data-hide-track="${t.id}">비공개로 전환</button>`:['failed','hidden'].includes(t.status)?`<button class="small-button" data-retry-track="${t.id}">${t.status==='hidden'?'다시 공개':'다시 변환'}</button>`:''}</div></div>`).join(''):'아직 업로드한 곡이 없습니다.'}</div>${section('작곡가 · 제작자 프로필')}<form id="producer-form" class="surface upload-form profile-editor">${imageField('작곡가 / 제작자 사진','image',profileImageURL(d.producer,'producer'),true)}${formField('작곡가 / 제작자 이름','name','text',d.producer?.name||me.name,'required maxlength="60"')}${bioField('작곡가 / 제작자 소개','bio',d.producer?.bio||'')}<button class="primary-button">제작자 프로필 저장</button><p class="form-error" role="alert"></p></form>${section('AI 가수 · 아티스트 프로필')}<div class="artist-editors">${d.artists.length?d.artists.map(a=>`<details class="surface artist-editor"><summary>${portrait(a,'artist')}<div><strong>${esc(a.name)}</strong><span>${esc(a.genre)} · 사진과 소개 수정</span></div>${icon('chevron')}</summary><form class="upload-form artist-form" data-id="${a.id}">${imageField('AI 가수 / 아티스트 사진','image',profileImageURL(a,'artist'),true)}${formField('AI 가수 / 아티스트 이름','name','text',a.name,'required maxlength="60"')}${bioField('AI 가수 / 아티스트 소개','bio',a.bio)}${genreField(a.genre)}<button class="primary-button">아티스트 프로필 저장</button><p class="form-error" role="alert"></p></form></details>`).join(''):'<p class="quiet">음원 업로드에서 첫 AI 아티스트를 등록해보세요.</p>'}</div>`;}
function karaokeCheckHTML(){return `<label class="checkbox-line rights-check"><input name="karaoke" type="checkbox" required> <span>${esc(AifectSite.KARAOKE_TERMS_TEXT)} <a href="/terms#karaoke" target="_blank" rel="noopener">약관 보기</a></span></label>`;}
function karaokeStatusHTML(t){if(t.karaoke_at)return karaokePanelHTML(t);return `<div class="rights-check karaoke-optin"><p>이 곡은 노래방 MR 제공 · 커버 허락 조항이 생기기 전에 올라왔습니다. 동의하면 노래방과 커버곡 기능에 포함됩니다.</p><label class="checkbox-line"><input type="checkbox" id="karaoke-accept"> <span>${esc(AifectSite.KARAOKE_TERMS_TEXT)} <a href="/terms#karaoke" target="_blank" rel="noopener">약관 보기</a></span></label><button type="button" class="small-button" data-karaoke-track="${t.id}">동의하고 노래방에 포함하기</button></div>`;}
const KARAOKE_STATE={queued:'노래방 MR을 만들 차례를 기다리고 있어요. 한 곡씩 차례로 만들어서 시간이 걸릴 수 있어요.',processing:'보컬을 분리해 노래방 MR을 만들고 있어요.',ready:'노래방 MR이 준비됐어요. 들어보고 보컬이 남아 있으면 직접 만든 반주 파일로 바꿀 수 있어요.'};
const KARAOKE_WORDS={ready:'가사 단어별 싱크까지 완료됐어요.',attention:'가사 단어별 싱크를 맞췄어요. 일부 구간은 정확하지 않을 수 있어요.',failed:'가사 단어별 싱크를 맞추지 못했어요. 등록한 가사가 실제로 부르는 내용과 같은지 확인해주세요.'};
function karaokePanelHTML(t){const k=t.karaoke,busy=k&&['queued','processing'].includes(k.state);
 const state=!k?'곡 변환이 끝나면 노래방 MR을 자동으로 만듭니다.':k.state==='failed'?esc(k.error||'노래방 MR을 만들지 못했습니다.'):k.state==='processing'&&k.mr_source==='upload'?'올린 반주 파일을 변환하고 있어요.':KARAOKE_STATE[k.state]||'';
 const words=!k?'':!k.has_lyrics?'싱크 가사가 없어서 노래방에 가사가 나오지 않아요. 아래에서 가사를 싱크로 등록하면 단어별 싱크를 자동으로 맞춥니다.':busy?'가사 단어별 싱크도 함께 맞춥니다.':KARAOKE_WORDS[k.words_state]||'';
 return `<div class="rights-check karaoke-panel"><div class="form-section-heading"><h2>노래방 MR</h2></div><p><strong>${state}</strong></p>${words?`<p class="field-help">${words}</p>`:''}${k?.mr_ready?`<audio controls preload="none" src="/api/studio/tracks/${t.id}/karaoke/mr?v=${k.updated}"></audio>`:''}<div class="inline-actions"><button type="button" class="small-button" data-karaoke-regenerate="${t.id}" ${busy?'disabled':''}>자동으로 다시 만들기</button><label class="small-button">내 반주 파일로 바꾸기<input type="file" accept=".wav,.flac,.mp3" data-karaoke-upload="${t.id}" hidden></label></div><p class="field-help">직접 올리는 반주는 원곡과 길이가 같은 WAV·FLAC·MP3 파일이어야 해요. (80MB 이하)</p><p class="field-help">노래방 MR 제공 · 커버 허락 동의: ${new Date(t.karaoke_at*1000).toLocaleDateString('ko-KR')} · 약관 ${esc(t.karaoke_terms)}</p></div>`;}
function trackEditHTML(t,d){return heading('곡 · 커버 · 가사 수정','수정한 정보는 공개된 곡에 바로 반영됩니다.')+`<a href="#studio" class="text-link">← 스튜디오로</a><form id="track-edit-form" data-id="${t.id}" class="surface upload-form track-editor">${imageField('앨범 / 싱글 커버','image',t.has_cover?`/media/${t.id}/cover?v=${t.cover_version||'original'}`:'')}${formField('곡 제목','title','text',t.title,'required maxlength="120"')}<label class="form-field">AI 아티스트<select name="artist_id">${d.artists.map(a=>`<option value="${a.id}" ${a.id===t.artist_id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label>${genreField(t.genre)}${formField('태그 (쉼표로 구분)','tags','text',t.tags,'maxlength="300"')}<label class="form-field">곡 소개<textarea name="description" maxlength="4000">${esc(t.description)}</textarea></label>${formField('사용한 AI 도구','ai_tool','text',t.ai_tool,'required maxlength="100"')}${participationFields(t.participation)}${karaokeStatusHTML(t)}${lyricsEditorHTML(t)}<button class="primary-button">곡 정보 저장</button><p class="form-error" role="alert"></p></form>`;}
function bindImageInputs(root=document){
 root.querySelectorAll('[data-image-input]').forEach(input=>{
  if(input.dataset.bound)return;input.dataset.bound='true';
  const box=input.closest('.image-field'),preview=box.querySelector('.image-preview'),original=preview.innerHTML,status=box.querySelector('.image-selection'),reset=box.querySelector('[data-reset-image]');let url='';
  input.onchange=async()=>{if(url)URL.revokeObjectURL(url);status.textContent='';input.setCustomValidity('');const file=input.files[0];if(!file){preview.innerHTML=original;reset.hidden=true;return;}
   try{await validateImage(file);url=URL.createObjectURL(file);preview.innerHTML='';const img=document.createElement('img');img.src=url;img.alt='선택한 이미지 미리보기';preview.append(img);status.textContent=file.name;reset.hidden=false;}
   catch(e){input.setCustomValidity(e.message);input.reportValidity();status.textContent=e.message;preview.innerHTML=original;reset.hidden=false;}
  };reset.onclick=()=>{input.value='';input.onchange();};
 });
}
async function validateImage(file){if(!file?.size)return;if(file.size>5*1024*1024)throw new Error('이미지는 5MB 이하로 업로드해주세요.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('JPG·PNG·WebP 이미지를 선택해주세요.');const bitmap=await createImageBitmap(file).catch(()=>{throw new Error('이미지를 열 수 없습니다. 다른 파일을 선택해주세요.');});const ok=bitmap.width>0&&bitmap.height>0;bitmap.close();if(!ok)throw new Error('올바른 이미지 파일을 선택해주세요.');}
function textFields(fd){return Object.fromEntries([...fd].filter(([,v])=>typeof v==='string'));}
function bindStudioForms(){
 bindImageInputs();bindLyricsEditor();
 if($('#upload-artist'))$('#upload-artist').onchange=e=>{$('#upload-artist-fields').innerHTML=artistUploadFields(studioData.artists.find(a=>a.id===e.target.value));bindImageInputs($('#upload-artist-fields'));};
 const producer=$('#producer-form');if(producer)producer.onsubmit=busyForm(producer,async fd=>{await validateImage(fd.get('image'));const {id}=await api('/api/studio/profile','PUT',textFields(fd));if(fd.get('image')?.size)await uploadFile(`/api/studio/producers/${id}/image`,fd.get('image'));toast('제작자 사진과 소개를 저장했습니다.');await render();});
 document.querySelectorAll('.artist-form').forEach(form=>{form.onsubmit=busyForm(form,async fd=>{await validateImage(fd.get('image'));await api(`/api/studio/artists/${form.dataset.id}`,'PUT',textFields(fd));if(fd.get('image')?.size)await uploadFile(`/api/studio/artists/${form.dataset.id}/image`,fd.get('image'));toast('AI 아티스트 사진과 소개를 저장했습니다.');await render();});});
 const mr=$('[data-karaoke-upload]');if(mr)mr.onchange=async()=>{const file=mr.files[0];if(!file)return;const ext=file.name.split('.').pop().toLowerCase();
  if(!['wav','flac','mp3'].includes(ext)||file.size>80*1024*1024){toast('반주 파일은 80MB 이하 WAV·FLAC·MP3만 올릴 수 있어요.');mr.value='';return;}
  try{toast('반주 파일을 올리고 있어요…');await uploadFile(`/api/studio/tracks/${mr.dataset.karaokeUpload}/karaoke/mr?ext=${ext}`,file);toast('반주 파일을 올렸어요. 변환이 끝나면 여기에서 들을 수 있어요.');await render();}catch(e){toast(e.message);mr.value='';}};
 const track=$('#track-edit-form');if(track)track.onsubmit=busyForm(track,async fd=>{applyLyrics(fd);await validateImage(fd.get('image'));await api(`/api/studio/tracks/${track.dataset.id}`,'PUT',{...textFields(fd),participation:fd.getAll('participation').join(', ')});if(fd.get('image')?.size)await uploadFile(`/api/studio/tracks/${track.dataset.id}/image`,fd.get('image'));toast('곡 정보와 앨범 커버를 저장했습니다.');await render();});
}
